'use strict';
const $=s=>document.querySelector(s), e=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=x=>Number(x).toLocaleString('ko-KR')+'원', enc=encodeURIComponent;
let cfg,me,route='education',chatSession=null,chatMessages=[],threadId=null,files=[],estimate=null,fields=null,selectedDate=null,calendarMonth=new Date(),selectedPlan='lite',selectedAdd=new Set(),pub=null,renderId=0,publicMode=location.pathname.startsWith('/c/')||location.pathname.startsWith('/widget/'),slug=location.pathname.split('/')[2];
const btn=(text,fn,cls='')=>`<button class="${cls}" onclick="${fn}">${e(text)}</button>`, card=(title,body)=>`<section class="card"><h2>${e(title)}</h2>${body}</section>`, label=(text,body)=>`<label class="label">${e(text)}</label>${body}`, input=(id,v='',type='text',ph='')=>`<input id="${id}" type="${type}" value="${e(v)}" placeholder="${e(ph)}">`, ta=(id,v='')=>`<textarea id="${id}">${e(v)}</textarea>`, select=(id,opts,v)=>`<select id="${id}">${opts.map(([k,n])=>`<option value="${e(k)}" ${k===v?'selected':''}>${e(n)}</option>`).join('')}</select>`, pageTop=(h,s)=>`<div class="top"><div><h1>${e(h)}</h1><p class="muted">${e(s)}</p></div><span class="tag">${cfg.demo?'로컬 개발 환경':'연동 검증 환경'}</span></div>`, has=k=>me?.entitlements.includes(k), go=p=>location.hash=p, val=id=>$('#'+id).value, checked=id=>$('#'+id).checked;
const names={agents:'AI 상담원 관리',inbox:'상담 목록',preview:'채팅창 미리보기',education:'AI 교육시키기',calendar:'일정표 보기',customers:'고객·업무 관리',channels:'외부 채널 연동',alerts:'알림',settings:'설정',pricing:'요금제 및 결제'}, states={open:'진행 중',pending:'승인 대기',pending_payment:'결제 확인 대기',confirmed:'확정',cancelled:'취소',completed:'완료',resolved:'처리 완료',draft:'작성 중'};
async function api(path,body,method){let r=await fetch(path,{method:method||(body===undefined?'GET':'POST'),headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===204)return {};let x=await r.json().catch(()=>({detail:'서버 응답 오류'}));if(!r.ok){let err=new Error(typeof x.detail==='string'?x.detail:JSON.stringify(x.detail));err.status=r.status;throw err}return x}
function toast(text){document.querySelector('.toast')?.remove();let d=document.createElement('div');d.className='toast';d.textContent=text;document.body.append(d);setTimeout(()=>d.remove(),3500)}
function modal(title,html){$('.modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="modal" onclick="if(event.target===this)this.remove()"><div class="card"><h2>${e(title)}</h2>${html}<div style="margin-top:12px">${btn('닫기',"this.closest('.modal').remove()")}</div></div></div>`)}
async function act(fn){try{await fn()}catch(x){toast(x.message)}}
async function refresh(){me=await api('/api/me')}
function locked(key,description){let a=cfg.catalog.addons.find(x=>x.id===key);return card(a?.name||'추가 기능',`<p>${e(description)}</p><div class="banner">월 ${money(a?.price||0)} · 추가 결제 기능</div>${btn('요금제 보기',"go('pricing')",'primary')}`)}
function shell(body){
 const groups=[
  ['상담 관리',[['inbox','상담 목록','▣'],['preview','채팅창 미리보기','▤'],['education','AI 교육시키기','◇'],['agents','AI 상담원 관리','♙']]],
  ['업무 관리',[['calendar','일정표 보기','▦'],['customers','고객·업무 관리','▧']]],
  ['서비스 관리',[['channels','외부 채널 연동','♧'],['developer','개발자 센터','⌘'],['alerts','알림','♢'],['settings','설정','⚙'],['pricing','요금제 및 결제','▱'],['features','전체 기능','☷'],['credits','교육 크레딧','◈'],['addons','추가 기능','⊕'],['orders','주문·구독 내역','▤']]]
 ];
 if(me.operator)groups.push(['플랫폼 운영자 전용',[['invites','초청 및 체험 관리','♙'],['costs','AI 사용량 및 원가','▥']]]);
 const quota=me.quota??(cfg.catalog.plans.find(x=>x.id===me.plan)?.quantity||1);
 const used=Math.max(0,quota-me.remaining),pct=Math.max(0,Math.min(100,used/quota*100));
 const nav=groups.map(([title,items])=>`<div class="nav-group"><div class="nav-title">${e(title)}</div>${items.map(([p,n,icon])=>`<button type="button" class="${route===p?'active':''}" onclick="go('${p}')"><span class="nav-icon" aria-hidden="true">${icon}</span><span>${e(n)}</span>${p==='calendar'&&!has('calendar')?'<span class="nav-lock">⌑</span>':''}</button>`).join('')}</div>`).join('');
 return `<div class="layout"><aside class="app-sidebar"><div class="brand sidebar-brand"><span><b>CS</b> AI</span><button class="mobile-toggle" onclick="this.closest('aside').classList.toggle('open')" aria-label="메뉴 열기">☰</button></div><div class="sidebar-tenant"><div class="tenant-avatar">▣</div><div><strong>${e(me.settings.brand)}</strong><small>${me.operator?'운영자 계정':me.trial?'초청 체험':e(me.plan.toUpperCase()+' 요금제')}</small></div></div><nav>${nav}</nav><div class="sidebar-bottom"><div class="usage-label"><span>이번 달 상담량</span><b>${used.toLocaleString()} / ${quota.toLocaleString()}회</b></div><div class="usage-track"><span style="width:${pct}%"></span></div><div class="usage-label"><span>교육 크레딧</span><b>${me.credits.toLocaleString()} C</b></div>${me.trial?`<p class="sidebar-trial">예약 체험 ${me.trial.bookings_remaining}건 남음</p>`:''}<button class="usage-link" onclick="go('pricing')">이용량 및 요금제 관리</button><button class="sidebar-logout" onclick="logout()">로그아웃 ↗</button></div></aside><main>${cfg.demo?'<div class="demo-note">개발 환경 · 실제 결제 없음 · '+(cfg.ai_connected?'실제 AI API 연결됨':'AI 응답은 로컬 규칙 기반 데모')+'</div>':''}${body}</main></div>`
}
function home(){return `<div class="hero"><div class="hero-inner"><div class="brand"><b>CS</b> AI <span class="brand-subtitle" aria-label="나의 클론 상담사"><span class="brand-typed" aria-hidden="true">나의 클론 상담사</span></span></div><span class="tag">AI 고객 상담 매니저</span><h1>나처럼 상담하는 AI</h1><p class="muted" style="font-size:15px;line-height:1.8;margin:0 0 30px">직접 교육하고, 링크 하나로 시작하세요.<br>당신의 고객 상담을 대신합니다.</p><div class="stack"><button class="google auth-button" onclick="google()"><img src="/assets/google-g.svg" alt=""><span>Google로 시작하기</span></button>${cfg.demo&&!cfg.shared_test?'<button class="primary auth-button" onclick="location.href=\'/auth/demo\'">로컬 테스트로 들어가기</button>':''}<button class="naver auth-button" onclick="modal('준비 중','<p>네이버 로그인은 준비 중입니다.</p>')"><img src="/assets/naver-n.svg" alt=""><span>네이버로 시작하기</span></button><button class="kakao auth-button" onclick="modal('준비 중','<p>카카오 로그인은 준비 중입니다.</p>')"><img src="/assets/kakao-talk.svg" alt=""><span>카카오로 시작하기</span></button></div><p class="muted" style="margin-top:24px">개발 환경 · 운영 약관 및 개인정보처리방침은 출시 전 확정</p></div></div>${landingBenefits()}`}
function google(){if(cfg.google_configured)location.href='/auth/google';else modal('준비 중','<p>Google 로그인 설정을 확인하고 있습니다.</p>')}
async function logout(){await api('/api/logout',{});location.href='/'}
function phone(s,test=false,preview=false){return `<div class="phone theme-${e(['dark','toss','messenger','premium'].includes(s.theme)?s.theme:'dark')} density-${e(['normal','compact','roomy'].includes(s.density)?s.density:'normal')} radius-${s.bubble_radius==='square'?'square':'rounded'}" style="--chat-color:${e(s.color&&/^#[0-9a-f]{6}$/i.test(s.color)?s.color:'#3182F6')}"><div class="phone-head"><div class="avatar">${s.logo&&s.logo.startsWith('data:image/png;base64,')?`<img src="${e(s.logo)}" alt="업체 로고" style="width:100%;height:100%;object-fit:contain;border-radius:inherit">` :'◎'}</div><div class="phone-identity"><strong>${e(s.brand)}</strong><div class="chat-online"><span></span> 24시간 상담 가능${test?' · 관리자 테스트':''}</div></div><button type="button" class="chat-menu" onclick="chatMenu()" aria-label="채팅 메뉴">⋮</button></div>${s.notice||s.links?.length?`<div class="notice"><details><summary>${e(s.notice||'공식 판매처 안내')}</summary><div class="linklist">${(s.links||[]).map(l=>`<a href="${e(l.url)}" target="_blank" rel="noopener noreferrer">${e(l.name)} 바로가기</a>`).join('')}</div></details></div>`:''}<div class="messages" id="messages"><div class="chat-day">오늘</div><div class="chat-author">${e(s.brand)}</div><div class="bubble">${e(s.welcome)}</div>${chatMessages.map(m=>bubble(m.role,m.body)).join('')}</div><div class="chat-bottom"><div class="chat-suggestions"><button type="button" onclick="quickChat('가격 안내')">가격 안내</button><button type="button" onclick="quickChat('예약 문의')">예약 문의</button><button type="button" onclick="quickChat('위치 안내')">위치 안내</button><button type="button" onclick="quickChat('예약 취소')">예약 취소</button></div><form class="compose" onsubmit="event.preventDefault();sendChat()"><textarea id="msg" rows="1" maxlength="2000" placeholder="메시지를 입력하세요" onkeydown="if(event.key==='Enter'&&!event.shiftKey&&!event.isComposing){event.preventDefault();sendChat()}"></textarea><button class="primary" id="send" aria-label="메시지 보내기">↑</button></form>${publicMode?`<div class="row" style="padding:4px 12px">${s.calendar?btn('내 예약 확인','customerBookings()'):''}${s.requests?.length?btn('업무 요청','customerRequest()'):''}</div>`:''}<div class="phone-foot">${s.unbrand?'AI 상담':'AI 상담원이 응대하고 있습니다.'} ${cfg.demo?' · 로컬 검증용':''}</div></div></div>`}
function quickChat(text){let field=$('#msg');if(!field||sending)return;field.value=text;field.focus();sendChat()}
function chatMenu(){modal('채팅 메뉴',btn('상담 링크 복사',"act(async()=>{await navigator.clipboard.writeText(location.origin+'/c/'+(me?.slug||slug));$('.modal').remove();toast('복사했습니다')})"))}
function bubble(role,body){let text=String(body??'');let parts=text.split(/(https:\/\/[^\s<>"']+)/g);return `<div class="bubble ${role==='user'?'user':''}">${parts.map((x,i)=>{if(i%2===0)return e(x);try{let u=new URL(x);if(u.protocol==='https:')return `<a href="${e(u.href)}" rel="noopener noreferrer" target="_blank">${e(x)}</a>`}catch{}return e(x)}).join('')}</div>`}
async function getChatSession(){if(chatSession)return chatSession;let saved=publicMode?sessionStorage.getItem('csai-session-'+slug):null;if(saved){try{chatMessages=await api('/api/session/'+enc(saved)+'/messages');chatSession=saved;return saved}catch{sessionStorage.removeItem('csai-session-'+slug)}}let s=await api('/api/session',publicMode?{slug}:{test:true});chatSession=s.token;if(publicMode)sessionStorage.setItem('csai-session-'+slug,chatSession);return chatSession}
let sending=false;
const motionDots='<span class="motion-dots" aria-hidden="true"><i></i><i></i><i></i></span>';
function pendingChat(){let area=$('#messages');if(!area)return null;let node=document.createElement('div');node.className='chat-pending';node.setAttribute('role','status');node.innerHTML=motionDots+'<span>답변 준비 중</span>';area.append(node);area.scrollTop=area.scrollHeight;return node;}
async function streamReply(node,body){
  if(!node?.isConnected)return;
  if(matchMedia('(prefers-reduced-motion: reduce)').matches){node.outerHTML=bubble('assistant',body);return}
  const area=node.parentElement,words=String(body).match(/\S+\s*/g)||[String(body)];
  node.className='bubble streaming-reply';node.removeAttribute('role');node.innerHTML='<div class="stream-text"></div>';
  const content=node.firstChild,make=(x,k,c)=>({x,v:0,t:x,k,c}),width=make(110,260,26),height=make(40,260,26),letters=[];
  node.style.width='110px';node.style.height='40px';
  const finalWidth=Math.min(area.clientWidth*.86,300),interval=Math.min(70,3000/words.length);
  let done=false,last=performance.now();
  function frame(now){if(!node.isConnected||done)return;const dt=Math.min((now-last)/1000,1/30)/4;last=now;
    for(let i=0;i<4;i++)for(const s of [width,height,...letters.map(x=>x.spring)]){const a=-s.k*(s.x-s.t)-s.c*s.v;s.v+=a*dt;s.x+=s.v*dt}
    node.style.width=Math.max(40,width.x)+'px';node.style.height=Math.max(26,height.x)+'px';
    for(const item of letters){const v=Math.max(0,Math.min(1,item.spring.x));item.el.style.opacity=v;item.el.style.transform=`translateY(${(1-item.spring.x)*6}px)`;item.el.style.filter=v<.98?`blur(${(1-v)*4}px)`:'none'}
    area.scrollTop=area.scrollHeight;requestAnimationFrame(frame)}
  requestAnimationFrame(frame);width.t=finalWidth;
  for(const word of words){if(!node.isConnected)break;const el=document.createElement('span');el.className='stream-word';el.textContent=word;content.append(el);letters.push({el,spring:make(0,340,26)});letters.at(-1).spring.t=1;height.t=Math.max(40,content.scrollHeight+18);await new Promise(r=>setTimeout(r,interval))}
  await new Promise(r=>setTimeout(r,260));done=true;if(node.isConnected)node.outerHTML=bubble('assistant',body);
}
async function sendChat(){if(sending)return;let text=val('msg').trim();if(!text)return;sending=true;$('#send').disabled=true;let waiting=pendingChat();try{let token=await getChatSession();let result=await api('/api/chat',{token,message:text,clientMessageId:crypto.randomUUID()});chatMessages.push({role:'user',body:text},{role:'assistant',body:result.reply});if(!$('#messages')||!$('#msg'))return;waiting?.insertAdjacentHTML('beforebegin',bubble('user',text).replace('class="bubble ','class="bubble motion-new '));$('#msg').value='';await streamReply(waiting,result.reply);if(result.booking)await bookingForm(token,result.bookingData||{});if(result.workDraft&&publicMode)showWorkDraft(result.workDraft);$('#messages').scrollTop=$('#messages').scrollHeight;if(!publicMode)await refresh()}catch(x){if(x.status===402&&!publicMode)modal('상담 이용 안내','<p>무료 테스트 1회 또는 월 답변 사용량을 모두 사용했습니다.</p>'+btn('요금제 보기',"$('.modal').remove();go('pricing')",'primary')+btn('건너뛰기',"$('.modal').remove();go('education')"));else toast(x.message)}finally{waiting?.remove();sending=false;if($('#send'))$('#send').disabled=false}}
async function preview(test=false){let appearance=await api('/api/appearance');return pageTop(test?'AI 상담 테스트':'채팅창 미리보기',test?'첫 AI 답변 1회 무료 · 이후 구독 필요':'고객은 로그인 없이 상담합니다.')+`<div class="grid"><div>${phone({...me.settings,...appearance},test,!test)}</div><div>${card('전용 상담 링크',`<p>현재 ${me.enabled?'활성화':'비활성화'} 상태입니다.</p>${input('public-link',location.origin+'/c/'+me.slug)}<div class="row" style="margin:10px 0">${btn('링크 복사',"act(async()=>{await navigator.clipboard.writeText(val('public-link'));toast('복사했습니다')})")}${btn('공개 설정',"act(async()=>{await api('/api/settings',{enabled:!me.enabled},'PATCH');await refresh();render()})",'primary')}</div>${!me.public_access?'<p class="muted">유료 구독 후 공개 채팅 및 QR을 사용할 수 있습니다.</p>':`<img src="/api/qr" width="132" height="132" alt="상담 링크 QR코드"><a href="/api/qr" download="csai-qr.png">QR 저장</a>`}<div style="margin-top:12px">${btn('AI 상담 테스트',"go('test')",'primary')}</div>`)}${card('상담 사용량',`<div class="price">${me.remaining.toLocaleString()}회 남음</div><p class="muted">테스트와 실고객 상담은 동일한 사용량으로 차감됩니다.</p>`)}</div></div>`}
let educationAgent='';
async function education(){files=await api('/api/files');let jobs=await api('/api/training'),faq=await api('/api/faq'),agent=has('extra_agent')?await api('/api/agents'):null;if(!agent)educationAgent='';return pageTop('AI 교육시키기','자료와 직접 지침으로 나만의 상담원을 만드세요.')+`<div class="grid">${card('교육 현황',`<div class="price">${me.credits} 크레딧</div><p class="muted">최초 무료 20크레딧 · 모든 AI 교육은 크레딧 차감</p>${btn('교육 크레딧 보기',"go('credits')")}${btn('말투 설정',"go('style')")}`)}${card('교육 자료 등록',`<input type="file" id="upload" multiple accept=".txt,.md,.csv,.pdf,.png,.jpg,.jpeg,.webp,.docx,.xlsx,.hwpx"><p class="muted">파일당 5MB · PDF 30페이지 · HWPX 지원 · 구형 HWP는 PDF로 변환 · 사진 개인정보는 사전 제거</p>${btn('파일 업로드','uploadFiles()','primary')}${label('공개 웹페이지 URL',input('education-url','','url','https://'))}${btn('웹페이지 자료 가져오기','importEducationUrl()')}`)}</div>${card('자료 선택 및 AI 교육',`${files.map(f=>`<div class="row line"><input class="check file-check" type="checkbox" value="${e(f.id)}" checked><span>${e(f.name)} <small>${f.chars}자</small></span>${btn('삭제',`act(async()=>{await api('/api/files/${f.id}',undefined,'DELETE');render()})`)}</div>`).join('')||'<p class="muted">등록된 자료가 없습니다.</p>'}${agent?label('교육 대상',select('training-agent',[['','기본 상담원'],[agent.id,agent.settings.brand]],educationAgent)):''}${label('추가 교육 내용',ta('training-text'))}${btn('교육 비용 확인','estimateTraining()','primary')}<div id="estimate"></div>`)}${card('교육 결과 검토 및 반영',jobs.filter(j=>j.result).map(j=>`<div class="line"><strong>${e(j.agent?'추가 상담원':'기본 상담원')} · ${e(j.state==='published'?'반영 완료':'검토 필요')} · ${j.cost} C</strong><pre class="scrolltext">${e(JSON.stringify(j.result,null,2))}</pre>${j.state==='review'?btn('결과 수정',`reviewModal('${j.id}')`)+btn('승인 및 상담에 반영',`act(async()=>{await api('/api/training/${j.id}/publish',{});await refresh();render()})`,'primary'):''}</div>`).join('')||'<p class="muted">교육을 실행하면 결과가 표시됩니다. 승인 전에는 고객 상담에 반영되지 않습니다.</p>')}${card('직접 모범 답변 교육',`${label('질문',input('faq-q'))}${label('답변',ta('faq-a'))}${btn('저장',"act(async()=>{showEducationQuote(await api('/api/faq',{q:val('faq-q'),a:val('faq-a')}))})",'primary')}${faq.map(f=>`<div class="line"><b>${e(f.q)}</b><p>${e(f.a)}</p>${btn('삭제',`act(async()=>{await api('/api/faq/${f.id}',undefined,'DELETE');render()})`)}</div>`).join('')}`)}${btn('AI 상담 테스트',"go('test')",'primary')}`}
async function uploadFiles(){await act(async()=>{let fs=[...$('#upload').files];if(!fs.length)throw Error('파일을 선택하세요.');for(let f of fs){if(f.size>5e6)throw Error('파일당 5MB 이하');let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});await api('/api/files',{name:f.name,data})}toast('자료 등록 완료');render()})}
async function estimateTraining(){await act(async()=>{estimate=await api('/api/training/estimate',{text:val('training-text'),agent:$('#training-agent')?.value||'',files:[...document.querySelectorAll('.file-check:checked')].map(x=>x.value)});$('#estimate').innerHTML=`<div class="banner">최대 ${estimate.maxCredits} 크레딧 예약 · 보유 ${estimate.credits} C<br>실제 사용량 차감 후 남은 예약분은 복구합니다.</div>${estimate.enough?btn('비용 확인 및 교육 시작','runTraining()','primary'):btn('크레딧 충전',"go('credits')")}`})}
async function runTraining(){await act(async()=>{if(!estimate)return;let area=$('#estimate');area.innerHTML='<div class="banner training-pending" role="status">'+motionDots+'<span>교육 분석 중…</span></div>';try{let r=await api('/api/training/'+estimate.id+'/run',{});toast(`교육 결과 생성 · ${r.cost} C 사용`);await refresh();render()}catch(err){if(area.isConnected)area.innerHTML='<p class="muted">교육 상태를 다시 확인해 주세요.</p>'+btn('교육 비용 다시 확인','estimateTraining()','primary');throw err}})}
function style(){let s=me.settings;return pageTop('상담 스타일 설정','AI가 답변할 말투와 기준을 설정하세요.')+card('말투 및 표현',`${label('말투',select('tone',['자연스럽고 정중하게','정중하고 전문적으로','친근하고 편안하게','자료의 기존 말투'].map(x=>[x,x]),s.tone))}<p><label><input class="check" id="emoji" type="checkbox" ${s.emoji?'checked':''}> 이모지 사용</label></p><p class="muted">상담 지침은 교육센터에서 크레딧을 사용해 변경할 수 있습니다.</p>${btn('상담 지침 교육',"educationAgent='';go('education')")}${label('첫 인사',input('welcome',s.welcome))}${label('미학습 질문 안내',ta('fallback',s.fallback))}${btn('저장',"saveStyle()",'primary')}`)}
async function saveStyle(){await act(async()=>{await api('/api/settings',{tone:val('tone'),emoji:checked('emoji'),welcome:val('welcome'),fallback:val('fallback')},'PATCH');await refresh();toast('저장 완료')})}
const modeLabels={general:'일반 상담',price:'가격 안내',location:'위치·영업시간',purchase:'구매처·결제 안내',unknown:'새로운 질문',booking:'예약 접수·확정',change:'예약 변경·취소',complaint:'불만 접수',email:'이메일 알림'};
function settings(){let s=me.settings;return pageTop('설정','업체 정보, 공식 구매처 및 업무별 권한을 설정합니다.')+`<div class="grid">${card('업체 정보',`${label('업체명',input('brand',s.brand))}${label('공지사항',ta('notice',s.notice))}${label('가격 안내',ta('price',s.price))}${label('위치 및 지도',ta('location',s.location))}${label('영업시간',ta('hours',s.hours))}${label('판매처 링크 (한 줄에 이름 | HTTPS 주소)',ta('links',s.links.map(x=>x.name+' | '+x.url).join('\n')))}${btn('업체 정보 저장','saveSettings()','primary')}`)}${card('업무별 응대 권한',Object.entries(modeLabels).map(([k,n])=>`<div class="row between line"><span>${e(n)}</span><div style="width:125px">${select('mode-'+k,[['auto','자동'],['manual','수동'],['off','OFF']],s.modes[k])}</div></div>`).join('')+btn('권한 저장','saveModes()','primary')+'<p class="muted">외부 환불은 안내만 가능합니다. 예약 자동 확정에는 추가 기능 권한이 필요합니다.</p>')}</div>`}
async function saveSettings(){await act(async()=>{let links=val('links').split('\n').filter(x=>x.trim()).map(x=>{let [name,url]=x.split('|').map(x=>x.trim());return {name,url}});await api('/api/settings',{brand:val('brand'),notice:val('notice'),price:val('price'),location:val('location'),hours:val('hours'),links},'PATCH');await refresh();toast('저장 완료')})}
async function saveModes(){await act(async()=>{await api('/api/settings',{modes:Object.fromEntries(Object.keys(modeLabels).map(k=>[k,val('mode-'+k)]))},'PATCH');await refresh();toast('권한 저장 완료')})}
async function inbox(){let ts=await api('/api/inbox');let detail=threadId?await api('/api/inbox/'+threadId):null;return pageTop('상담 목록','실제 상담 내역 및 담당자 대응 상태')+`<div class="grid">${card('상담 기록',ts.map(t=>`<div class="line"><small>${t.kind==='test'?'관리자 테스트':'고객 상담'} · ${e(states[t.status])}</small><p>${e(t.last||'새 상담')}</p>${btn('열기',`threadId='${t.id}';render()`)}</div>`).join('')||'<p class="muted">상담이 없습니다.</p>')}${card('상담 상세',detail?`<div class="stack">${detail.messages.map(m=>bubble(m.role,m.body)).join('')}</div><div class="row" style="margin-top:15px">${btn(detail.manual?'AI 상담 재개':'담당자 전환',`updateThread({manual:${!detail.manual}})`)}${btn('완료 처리',"updateThread({status:'resolved'})")}</div>${label('직접 답변',ta('staff-reply'))}${btn('답변 전송',"updateThread({reply:val('staff-reply'),manual:true})",'primary')}${['crm','quote','tasks','leads','complaints'].some(has)?btn('업무로 등록','convertModal()'):''}`:'<p class="muted">왼쪽 목록에서 상담을 선택하세요.</p>')}</div>`}
async function updateThread(body){await act(async()=>{await api('/api/inbox/'+threadId,body);render()})}
async function alerts(){let u=await api('/api/unknown');return pageTop('알림 및 미학습 질문','담당자 확인이 필요한 질문을 직접 교육하세요.')+card('새로운 질문',u.map(x=>`<div class="line"><span class="status">${e(states[x.status])}</span><h3>${e(x.q)}</h3>${x.status==='open'?`${ta('answer-'+x.id)}${btn('직접 답변으로 교육',`act(async()=>{showEducationQuote(await api('/api/faq',{q:(await api('/api/unknown')).find(z=>z.id==='${x.id}').q,a:val('answer-${x.id}'),unknown:'${x.id}'}))})`,'primary')}`:''}</div>`).join('')||'<p class="muted">확인할 질문이 없습니다.</p>')}
function localDate(iso){let d=new Date(iso),z=me?.settings.timezone||'Asia/Seoul';return new Intl.DateTimeFormat('sv-SE',{timeZone:z,year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function localTime(iso){return new Intl.DateTimeFormat('ko-KR',{timeZone:me?.settings.timezone||'Asia/Seoul',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(iso))}
function dateKey(y,m,d){return `${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`}
let calFilter='confirmed';
async function calendar(){if(!has('calendar'))return pageTop('일정표 보기','업체 맞춤 일정 양식 및 승인 관리')+locked('calendar','자체 일정표, 수동 관리, 맞춤 양식 설정을 이용할 수 있습니다.');let bs=await api('/api/bookings'),y=calendarMonth.getFullYear(),m=calendarMonth.getMonth(),first=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate();let day=selectedDate||dateKey(y,m,1);let filtered=bs.filter(b=>calFilter==='all'||calFilter==='pending'&&['pending','pending_payment'].includes(b.status)||b.status===calFilter);return pageTop('일정표 보기','확정된 일정만 기본 표시합니다.')+`<div class="row tab">${btn('맞춤 일정 양식',"go('fields')")}${btn('직접 일정 등록','manualBooking()','primary')}${btn('예약 설정',"go('booking-settings')")}${btn('담당자 관리','resourceModal()')}</div><div class="grid">${card(`${y}년 ${m+1}월`,`<div class="row between">${btn('이전','moveMonth(-1)')}${btn('다음','moveMonth(1)')}</div><div class="calendar" style="margin:12px 0">${['일','월','화','수','목','금','토'].map(d=>`<div class="muted">${d}</div>`).join('')}${Array(first).fill('<div></div>').join('')}${Array.from({length:n},(_,i)=>{let d=dateKey(y,m,i+1),cnt=filtered.filter(b=>localDate(b.start)===d).length;return `<button class="day ${day===d?'selected':''}" onclick="selectedDate='${d}';render()">${i+1}${cnt?`<span class="dot">● ${cnt}</span>`:''}</button>`}).join('')}</div><div class="row">${[['confirmed','확정'],['pending','승인·결제 대기'],['all','전체']].map(([k,v])=>btn(v,`calFilter='${k}';render()`,k===calFilter?'primary':'')).join('')}</div>`)}${card(day+' 일정',filtered.filter(b=>localDate(b.start)===day).map(b=>bookingCard(b)).join('')||'<p class="muted">표시할 일정이 없습니다.</p>')}${card('승인·결제 대기',bs.filter(b=>['pending','pending_payment'].includes(b.status)).map(b=>bookingCard(b)).join('')||'<p class="muted">대기 중인 일정이 없습니다.</p>')}</div>`}
function moveMonth(x){calendarMonth=new Date(calendarMonth.getFullYear(),calendarMonth.getMonth()+x,1);selectedDate=null;render()}
function bookingCard(b){return `<div class="line"><div class="row between"><strong class="blue">${e(localDate(b.start))} ${e(localTime(b.start))}–${e(localTime(b.end))}</strong><span class="status">${e(states[b.status])}</span></div>${b.fields.map(f=>b.payload[f.key]?`<div class="row between"><small>${e(f.label)}</small><span>${e(b.payload[f.key])}</span></div>`:'').join('')}<p class="muted">담당자: ${e(resources().find(r=>r.id===b.resource)?.name||b.resource)}</p><p class="muted">결제 확인: ${b.paid?'완료':'미확인 / 불필요 여부는 업체 정책 확인'}</p><div class="row">${['pending','pending_payment'].includes(b.status)?btn('확인 및 확정',`approveBooking('${b.id}',${b.status==='pending_payment'})`,'primary'):''}${['confirmed','pending','pending_payment'].includes(b.status)?btn('취소',`bookingAction('${b.id}','cancel')`):''}${b.status==='confirmed'?btn('완료',`bookingAction('${b.id}','complete')`):''}${b.status==='confirmed'&&has('change_booking')?btn('일정 변경',`changeBooking('${b.id}')`):''}${has('google_calendar')&&['confirmed','cancelled','completed'].includes(b.status)?btn('구글 일정 동기화',`syncCalendar('${b.id}')`):''}</div></div>`}
async function bookingAction(id,action){if(action==='cancel'&&!confirm('일정을 취소하시겠습니까?'))return;await act(async()=>{await api('/api/bookings/'+id,{action});render()})}
function approveBooking(id,pay){modal('예약 확정',`<p>고객이 확인한 양식과 예약 조건을 검토하세요.</p>${pay?'<label><input class="check" id="paid-ok" type="checkbox"> 외부 결제 내역을 직접 확인했습니다.</label>':''}${btn('확정',`act(async()=>{await api('/api/bookings/${id}',{action:'approve',paid:${pay?"checked('paid-ok')":"false"}});$('.modal').remove();render()})`,'primary')}`)}
function changeBooking(id){modal('일정 변경',label('변경 일시',input('new-start','','datetime-local'))+btn('변경 저장',`act(async()=>{await api('/api/bookings/${id}',{action:'change',start:val('new-start')});$('.modal').remove();render()})`,'primary'))}
function fieldsPage(){if(!has('calendar'))return locked('calendar','일정 양식은 일정표에 포함됩니다.');if(fields===null)fields=structuredClone(me.settings.fields);return pageTop('맞춤 일정 등록 양식','시작 및 종료 일시는 시스템 필수 항목입니다. 나머지는 업체가 정합니다.')+card('수집 항목',`<p class="muted">라벨 · 형식 · 필수 · 삭제 / 순서: 위·아래 버튼</p>${fields.map((f,i)=>`<div class="fieldrow"><input value="${e(f.label)}" onchange="fields[${i}].label=this.value">${select('type-'+i,['text','phone','number','date','time','select','boolean'].map((x,j)=>[x,['텍스트','전화','숫자','날짜','시간','선택','예/아니오'][j]]),f.type).replace('<select','<select onchange="fields['+i+'].type=this.value;render()"')}<label><input type="checkbox" class="check" ${f.required?'checked':''} onchange="fields[${i}].required=this.checked">필수</label>${btn('×',`fields.splice(${i},1);render()`)}</div><div class="row" style="margin-bottom:8px">${i>0?btn('↑',`swapField(${i},-1)`):''}${i<fields.length-1?btn('↓',`swapField(${i},1)`):''}${f.type==='select'?`<input placeholder="선택지: 쉼표 구분" value="${e((f.options||[]).join(','))}" onchange="fields[${i}].options=this.value.split(',').map(x=>x.trim()).filter(Boolean)">`:''}</div>`).join('')}<div class="row">${input('field-name','','text','새 항목 이름')}${btn('항목 추가',"addField()")}</div><div style="margin-top:15px">${btn('양식 저장','saveFields()','primary')}${btn('돌아가기',"go('calendar')")}</div>`)}
function addField(){let name=val('field-name').trim();if(!name)return;fields.push({key:'f_'+crypto.randomUUID().slice(0,8),label:name,type:'text',required:false});render()}
function swapField(i,d){[fields[i],fields[i+d]]=[fields[i+d],fields[i]];render()}
async function saveFields(){await act(async()=>{await api('/api/settings',{fields},'PATCH');await refresh();fields=structuredClone(me.settings.fields);toast('새 양식 버전을 저장했습니다.')})}
function bookingSettings(){if(!has('calendar'))return locked('calendar','일정표 권한이 필요합니다.');let s=me.settings;return pageTop('예약 설정','영업시간과 소요시간을 기준으로 예약 가능 여부를 검증합니다.')+card('예약 가능 시간',`${label('시간대',input('tz',s.timezone))}${label('영업 시작',input('open',s.open,'time'))}${label('영업 종료',input('close',s.close,'time'))}${label('기본 소요시간(분)',input('duration',s.duration,'number'))}${label('예약 사이 여유 시간(분)',input('buffer',s.buffer,'number'))}<p>휴무 요일</p><div class="row">${['월','화','수','목','금','토','일'].map((x,i)=>`<label><input type="checkbox" class="check closed" value="${i}" ${s.closed_days.includes(i)?'checked':''}>${x}</label>`).join('')}</div><p><label><input id="payment-required" type="checkbox" class="check" ${s.payment_required?'checked':''}> 외부 결제 확인 후 확정</label></p>${label('예약 모드',select('booking-mode',[['manual','수동 승인'],['auto','자동 확정'],['off','OFF']],s.modes.booking))}${btn('저장','saveBookingSettings()','primary')}<p class="muted">자동 확정은 자동 예약 옵션이 있어야 적용됩니다. 현재 단일 담당자/리소스 기준입니다.</p>`)}
async function saveBookingSettings(){await act(async()=>{await api('/api/settings',{timezone:val('tz'),open:val('open'),close:val('close'),duration:+val('duration'),buffer:+val('buffer'),closed_days:[...document.querySelectorAll('.closed:checked')].map(x=>+x.value),payment_required:checked('payment-required'),modes:{booking:val('booking-mode')}},'PATCH');await refresh();toast('예약 설정 저장')})}
function formFields(fs,prefix){return fs.map(f=>label(f.label+(f.required?' *':''),f.type==='select'?select(prefix+f.key,(f.options||[]).map(x=>[x,x]),''):f.type==='boolean'?select(prefix+f.key,[['','선택'],['예','예'],['아니오','아니오']],''):input(prefix+f.key,'',f.type==='phone'?'tel':f.type==='number'?'number':f.type==='date'?'date':f.type==='time'?'time':'text'))).join('')}
function payload(fs,prefix){return Object.fromEntries(fs.map(f=>[f.key,val(prefix+f.key)]))}
function manualBooking(){let s=me.settings;modal('수동 일정 등록',label('업체 현지 시작 일시',input('manual-start','','datetime-local'))+label('담당자',select('manual-resource',resources().map(r=>[r.id,r.name]),'default'))+formFields(s.fields,'manual-')+(s.payment_required?'<label><input type="checkbox" class="check" id="manual-paid"> 결제 확인 완료</label>':'')+btn('일정 등록','submitManual()','primary'))}
async function submitManual(){await act(async()=>{await api('/api/bookings',{start:val('manual-start'),resource:val('manual-resource'),payload:payload(me.settings.fields,'manual-'),paid:$('#manual-paid')?.checked||false});$('.modal').remove();render()})}
let activeForm=null,activeDraft=null;
async function bookingForm(token,prefill={}){await act(async()=>{activeForm=await api('/api/booking/form/'+enc(token));$('#booking-box')?.remove();$('#messages').insertAdjacentHTML('beforeend',`<section id="booking-box" class="card booking-form"><h3>예약 정보 확인</h3><p class="muted">시간대: ${e(activeForm.timezone)} · ${activeForm.duration}분</p>${label('담당자',select('booking-resource',activeForm.resources.map(r=>[r.id,r.name]),'default').replace('<select','<select onchange="clearSlots()"'))}${label('예약 날짜',input('booking-date','','date').replace('<input','<input onchange="clearSlots()"'))}${btn('가능 시간 조회','loadSlots()')}<div id="slots"></div>${formFields(activeForm.fields,'booking-')}${btn('예약 내용 확인','submitDraft()','primary')}<p class="muted">이 양식은 예약 접수에만 사용됩니다.</p></section>`);if(prefill.date)$('#booking-date').value=prefill.date;for(let [k,v] of Object.entries(prefill.payload||{})){let field=document.getElementById('booking-'+k);if(field)field.value=v}if(prefill.date){await loadSlots();if(prefill.time&&$('#booking-time')&&[...$('#booking-time').options].some(o=>o.value===prefill.time))$('#booking-time').value=prefill.time}$('#messages').scrollTop=$('#messages').scrollHeight})}
async function loadSlots(){await act(async()=>{let r=await api('/api/booking/availability',{token:chatSession,date:val('booking-date'),resource:val('booking-resource')});$('#slots').innerHTML=r.length?label('예약 시간',select('booking-time',r.map(x=>[x,x]),r[0])):'<p class="muted">예약 가능한 시간이 없습니다.</p>'})}
async function submitDraft(){await act(async()=>{if(!$('#booking-time'))throw Error('예약 시간을 먼저 조회하세요.');activeDraft=await api('/api/booking/draft',{token:chatSession,start:val('booking-date')+'T'+val('booking-time'),version:activeForm.template_version,resource:val('booking-resource'),payload:payload(activeForm.fields,'booking-')});$('#booking-box').innerHTML=`<h3>예약 내용 최종 확인</h3><p>${e(val('booking-date'))} ${e(val('booking-time'))} · ${activeForm.duration}분 · ${e(activeForm.resources.find(r=>r.id===activeDraft.resource)?.name||activeDraft.resource)}</p>${activeDraft.fields.map(f=>`<div class="row between"><small>${e(f.label)}</small><span>${e(activeDraft.payload[f.key]||'')}</span></div>`).join('')}<p class="muted">${activeForm.payment_required?'결제 확인 후 최종 확정됩니다.':'업체 설정에 따라 자동 확정 또는 승인 대기됩니다.'}</p>${btn('확정 요청','confirmDraft()','primary')}${btn('다시 작성','bookingForm(chatSession)')}`})}
async function confirmDraft(){await act(async()=>{let r=await api('/api/booking/'+activeDraft.id+'/confirm',{token:chatSession,confirmation:activeDraft.token});$('#booking-box').innerHTML=`<h3>${e(states[r.status])}</h3><p>예약번호: ${e(r.id)}</p><p class="muted">${r.status==='confirmed'?'예약이 확정되었습니다.':'업체 확인 후 확정됩니다.'}</p>`})}
async function customers(){let keys=['crm','quote','tasks','leads','complaints'];let a=keys.filter(has);let list=a.length?await api('/api/work'):[];let stats=has('stats')?await api('/api/stats'):null;return pageTop('고객·업무 관리','업무 요청을 정리하고 진행 상태를 관리합니다.')+(a.length?card('업무 등록',`${label('분류',select('work-kind',a.map(k=>[k,cfg.catalog.addons.find(x=>x.id===k).name]),a[0]))}${label('제목',input('work-title'))}${label('내용',ta('work-detail'))}${btn('등록',"act(async()=>{await api('/api/work',{kind:val('work-kind'),title:val('work-title'),details:val('work-detail')});render()})",'primary')}${list.map(x=>`<div class="line"><b>${e(x.title)}</b><p>${e(x.details)}</p><small>${e(states[x.status])}</small>${btn('수정',`workEdit('${x.id}')`)}${btn('삭제',`workDelete('${x.id}')`)}${x.status==='open'?btn('완료',`act(async()=>{await api('/api/work/${x.id}',{});render()})`):''}</div>`).join('')}`):locked('crm','고객 및 업무 기록을 관리합니다.'))+(has('crm')?await crmPanel():'')+(has('leads')?await leadPanel():'')+(has('quote')?await quotePanel(list):'')+(stats?await analyticsPanel():locked('stats','상담 건수와 미학습 질문을 확인합니다.'))+(has('export')?card('상담 기록 다운로드','<a href="/api/export">엑셀로 저장</a>'):locked('export','상담 내역을 엑셀 파일로 저장합니다.'))}
function channels(){let rows=[['widget','홈페이지 위젯','기존 사이트에 삽입하는 iframe 코드'],['naver','네이버 톡톡','파트너센터 API 및 웹훅 등록'],['kakao','카카오톡 채널','챗봇 관리자센터 스킬 및 콜백 승인'],['google_calendar','구글 캘린더','OAuth 권한 및 일정 동기화']];return pageTop('외부 채널 연동','교육한 상담원을 다양한 채널에 배치하세요.')+card('연동 채널',`<div class="row between line"><b>자체 웹 채팅</b><span class="pill">기본 포함</span></div>${rows.map(([k,n,d])=>`<div class="line"><div class="row between"><b>${e(n)}</b><span class="status">${k==='widget'&&has(k)?'코드 제공':k==='widget'?'유료 옵션':has(k)&&['naver','kakao'].includes(k)?'로컬 메시지 검증':'실연동 준비 중'}</span></div><p class="muted">${e(d)}</p>${k==='widget'&&has(k)?label('플로팅 위젯 설치 코드',ta('widget-code',`<script src="${location.origin}/assets/widget.js" data-slug="${me.slug}" defer></script>`))+btn('설치 코드 복사',"act(async()=>{await navigator.clipboard.writeText(val('widget-code'));toast('복사 완료')})")+`<p class="muted">홈페이지 HTML에 추가하면 우측 하단에 상담 버튼이 나타납니다.</p>`:btn('상세 안내',`channelHelp('${k}')`)+(has(k)&&['naver','kakao'].includes(k)?btn('연동 설정',`liveChannelModal('${k}')`):'')+(k==='google_calendar'&&has(k)?btn('캘린더 연결 관리','googleCalendarModal()'):'')+(cfg.demo&&has(k)&&['naver','kakao'].includes(k)?btn('메시지 테스트',`channelModal('${k}')`):'')}</div>`).join('')}`)}
function channelHelp(k){let a=cfg.catalog.addons.find(x=>x.id===k);modal(a.name,`<p>월 ${money(a.price)} 추가 옵션입니다.</p><p>${a.local?'로컬 구현이 있습니다. 공개 HTTPS 환경은 별도 검증이 필요합니다.':'공식 권한 및 실계정 검증 전까지 연결과 실제 판매를 차단합니다.'}</p>`)}
function table(headers,rs){return `<div class="wrap"><table><thead><tr>${headers.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rs.map(r=>`<tr>${r.map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function billingTabs(){return `<div class="tab">${btn('상담 요금',"go('pricing')")}${btn('전체 기능',"go('features')")}${btn('교육 크레딧',"go('credits')")}${btn('추가 기능',"go('addons')")}${btn('주문·구독 내역',"go('orders')")}</div>`}
function normalizeAdd(set){let a=new Set(set);if(a.has('channels')){a.delete('naver');a.delete('kakao')}for(let p of cfg.catalog.packages)if(a.has(p.id))p.includes.forEach(x=>a.delete(x));let covered=new Set([...a]);for(let p of cfg.catalog.packages)if(a.has(p.id))p.includes.forEach(x=>covered.add(x));for(let x of cfg.catalog.addons)if(a.has(x.id))x.requires.forEach(k=>{if(!covered.has(k))a.add(k)});return a}
function addonTotal(){let all=[...cfg.catalog.addons,...cfg.catalog.packages],a=normalizeAdd(selectedAdd);return all.filter(x=>a.has(x.id)).reduce((s,x)=>s+x.price,0)-(a.has('naver')&&a.has('kakao')?1900:0)}
function pricing(){let cat=cfg.catalog;return pageTop('요금제 및 결제','기본 상담 구독 + 교육 크레딧 + 유료 추가 기능')+billingTabs()+`<div class="grid">${card('AI 상담 월 구독',table(['요금제','월 답변','월 요금'],cat.plans.map(x=>[x.name,x.id==='free'?'최초 1회':x.quantity.toLocaleString(),money(x.price)])))}${card('맞춤 구독 구성',label('기본 요금제',select('plan',cat.plans.map(x=>[x.id,x.name+' · '+money(x.price)]),selectedPlan).replace('<select','<select onchange="selectedPlan=this.value;updatePrice()"'))+cat.addons.map(x=>`<div class="row between line"><label><input class="check" type="checkbox" ${selectedAdd.has(x.id)?'checked':''} onchange="toggleAdd('${x.id}',this.checked)"> ${e(x.name)} ${x.local?'':'· 준비 중'}</label><small>${money(x.price)}</small></div>`).join('')+cat.packages.map(x=>`<div class="row between line"><label><input class="check" type="checkbox" ${selectedAdd.has(x.id)?'checked':''} onchange="toggleAdd('${x.id}',this.checked)"> ${e(x.name)} 패키지</label><small>${money(x.price)}</small></div>`).join('')+`<div class="banner" id="quote-price"></div>${me.sandbox_allowed?btn('테스트용 구독 적용','applyPlan()','primary'):'<p>실제 결제 연동 준비 중</p>'}<p class="muted">실제 결제되지 않습니다. 준비 중 기능은 테스트 구독에도 실연동되지 않습니다.</p>`)}</div>`}
function toggleAdd(k,on){if(on)selectedAdd.add(k);else selectedAdd.delete(k);selectedAdd=normalizeAdd(selectedAdd);render()}
function updatePrice(){if($('#quote-price'))$('#quote-price').innerHTML=`<b>예상 월 ${money(cfg.catalog.plans.find(x=>x.id===selectedPlan).price+addonTotal())}</b><br><small>교육 및 알림톡·문자 별도</small>`}
async function applyPlan(){await act(async()=>{if(selectedPlan==='free'){await api('/api/demo/billing',{plan:'free',addons:[]});await refresh();render();return}await openCheckout({kind:'subscription',plan:selectedPlan,addons:[...normalizeAdd(selectedAdd)]})})}
function features(){return pageTop('전체 기능 비교','기본 포함, 별도 구매 및 준비 중 구분')+billingTabs()+card('기본 제공',table(['기능','무료 회원','유료 구독'],[['최초 교육 20크레딧','포함','포함'],['최초 상담 테스트','1회','월 제공량'],...cfg.catalog.basic.map(n=>n==='AI 교육 (크레딧 차감)'?[n,'크레딧 차감','크레딧 차감']:[n,['AI 교육 (크레딧 차감)','말투 설정','업체명·로고','공지·구매처 안내','기본 자동·수동 설정'].includes(n)?'포함':'미제공','포함'])]))+card('추가 결제 기능',table(['기능','무료 회원','유료 구독'],cfg.catalog.addons.map(x=>[x.name,'미제공',x.local?'추가 결제':'추가 결제 · 준비 중'])))}
function credits(){return pageTop('AI 교육 크레딧','고성능 AI 분석에만 사용량 차감')+billingTabs()+card('일회성 충전',table(['요금제','크레딧','금액'],cfg.catalog.education.map(x=>[x.name,x.quantity.toLocaleString(),money(x.price)]))+`<p>보유 크레딧: ${me.credits}</p>${me.sandbox_allowed?label('충전 상품',select('edu-sku',cfg.catalog.education.filter(x=>x.price).map(x=>[x.id,x.name+' · '+money(x.price)]),'mini'))+btn('로컬 테스트 충전',"act(async()=>{await openCheckout({kind:'education',sku:val('edu-sku')})})",'primary'):'<p>실제 결제 준비 중</p>'}<p class="muted">기본 말투 설정은 무료이며, AI 교육 및 모범 답변 교육은 크레딧이 차감됩니다.</p>`)}
function addons(){return pageTop('추가 기능 요금표','필요한 기능만 선택 · 월 추가 구독')+billingTabs()+[...new Set(cfg.catalog.addons.map(x=>x.group))].map(g=>card(g,table(['기능','월 요금','상태'],cfg.catalog.addons.filter(x=>x.group===g).map(x=>[x.name,money(x.price),x.local?'로컬 구현':'준비 중'])))).join('')+card('추가 기능 패키지',table(['패키지','월 요금','포함 기능'],cfg.catalog.packages.map(p=>[p.name,money(p.price),p.includes.map(i=>cfg.catalog.addons.find(x=>x.id===i)?.name).join(', ')])))+card('알림톡·SMS 별도 충전',table(['유형','건수','가격'],cfg.catalog.messages.map(x=>[x.name,x.quantity,money(x.price)])))}
async function render(){let id=++renderId;route=location.hash.slice(1)||'education';if(!me){$('#app').innerHTML=home();return}if(id!==renderId)return;let views={education,style,preview:()=>preview(),test:()=>preview(true),inbox,alerts,settings,calendar,fields:fieldsPage,'booking-settings':bookingSettings,customers,channels,developer,pricing,features,credits,addons,orders,agents,invites,costs};try{let html=await (views[route]||education)();if(id!==renderId)return;$('#app').innerHTML=shell(html);updatePrice()}catch(x){if(id===renderId)$('#app').innerHTML=shell(card('오류',`<p class="error">${e(x.message)}</p>${btn('다시 시도','render()')}`))}}
async function init(){try{if(location.hash.startsWith('#invite=')){sessionStorage.setItem('csai-invite',location.hash.slice(8));history.replaceState(null,'',location.pathname+'#education')}cfg=await api('/api/config');if(publicMode){pub=await api('/api/public/'+enc(slug));let saved=sessionStorage.getItem('csai-session-'+slug);if(saved){try{chatMessages=await api('/api/session/'+enc(saved)+'/messages');chatSession=saved}catch{sessionStorage.removeItem('csai-session-'+slug)}}$('#app').innerHTML=`<div class="public">${phone(pub)}</div>`;setInterval(async()=>{if(!chatSession||sending||$('#booking-box'))return;try{let ms=await api('/api/session/'+enc(chatSession)+'/messages');if(ms.length!==chatMessages.length){chatMessages=ms;$('#messages').innerHTML=`<div class="bubble">${e(pub.welcome)}</div>`+ms.map(m=>bubble(m.role,m.body)).join('');$('#messages').scrollTop=$('#messages').scrollHeight}}catch{}},4000);return}try{await refresh();selectedPlan=me.plan==='free'?'lite':me.plan;selectedAdd=new Set(me.addons);let invitation=sessionStorage.getItem('csai-invite');if(invitation){try{if(confirm('협력업체 무료 체험을 시작할까요?')){await api('/api/invites/accept',{code:invitation});await refresh();toast('무료 체험이 시작되었습니다.')}}catch(err){toast(err.message)}finally{sessionStorage.removeItem('csai-invite')}}}catch(x){if(x.status!==401)throw x}await render()}catch(x){$('#app').innerHTML=`<div class="hero"><div class="hero-inner"><h1>CS AI</h1><p class="error">${e(x.message)}</p><a href="/">처음으로</a></div></div>`}}
/* v0.2 operational UI */
function resources(){return me?.settings.resources||[{id:'default',name:'기본 담당자'}]}
function clearSlots(){if($('#slots'))$('#slots').innerHTML=''}
let resourceDraft=[];
function resourceModal(reset=true){if(reset)resourceDraft=structuredClone(resources());modal('담당자 관리',resourceDraft.map((r,i)=>`<div class="row line">${input('res-'+i,r.name)}${r.id!=='default'?btn('삭제',`resourceDraft.splice(${i},1);resourceModal(false)`):''}</div>`).join('')+btn('담당자 추가',"resourceDraft.forEach((r,i)=>r.name=val('res-'+i));resourceDraft.push({id:'r_'+crypto.randomUUID().slice(0,8),name:'새 담당자'});resourceModal(false)")+btn('저장',"act(async()=>{resourceDraft.forEach((r,i)=>r.name=val('res-'+i));await api('/api/settings',{resources:resourceDraft},'PATCH');$('.modal').remove();render()})",'primary')+'<p class="muted">담당자마다 중복 예약을 검사합니다. 영업시간은 업체 공통입니다.</p>')}
async function reviewModal(id){await act(async()=>{let j=(await api('/api/training')).find(x=>x.id===id);modal('교육 결과 수정',label('교육 결과 JSON',ta('review-json',JSON.stringify(j.result,null,2)))+btn('수정 저장',`act(async()=>{await api('/api/training/${id}/review',{result:JSON.parse(val('review-json'))},'PATCH');$('.modal').remove();render()})`,'primary'))})}
const oldEducation=education;education=async function(){let html=await oldEducation(),vs=await api('/api/knowledge/versions');return html+card('교육 버전 이력',vs.map(v=>`<div class="row between line"><span>${e(v.label)} · ${e(new Date(v.created*1000).toLocaleString())}</span>${btn('복원',`restoreVersion('${v.id}')`)}</div>`).join('')||'<p class="muted">교육을 승인할 때 이전 버전을 저장합니다.</p>')};
async function restoreVersion(id){if(!confirm('이전 교육 규칙으로 복원할까요? 현재 버전도 자동 백업됩니다.'))return;await act(async()=>{await api('/api/knowledge/versions/'+id+'/restore',{});render()})}
const oldCalendar=calendar;calendar=async function(){let html=await oldCalendar();if(!has('change_booking'))return html;let rs=await api('/api/booking-changes');return html+card('고객 예약 변경·취소 요청',rs.map(r=>`<div class="line"><b>${r.action==='cancel'?'취소':'일정 변경'} 요청</b><p>${e(r.booking)} · ${e(r.start?localDate(r.start)+' '+localTime(r.start):'')}</p><small>${e(r.state==='pending'?'승인 대기':r.state==='approved'?'승인 완료':'거절')}</small>${r.state==='pending'?btn('승인',`decideChange('${r.id}','approve')`,'primary')+btn('거절',`decideChange('${r.id}','reject')`):''}</div>`).join('')||'<p class="muted">요청이 없습니다.</p>')};
async function decideChange(id,action){await act(async()=>{await api('/api/booking-changes/'+id,{action});render()})}
async function customerBookings(){await act(async()=>{let t=await getChatSession(),r=await api('/api/customer/bookings/'+enc(t));modal('내 예약',r.bookings.map(b=>`<div class="line"><b>${e(states[b.status])} · ${e(new Date(b.start).toLocaleString())}</b>${b.fields.map(f=>`<p>${e(f.label)}: ${e(b.payload[f.key]||'')}</p>`).join('')}${r.canChange&&b.status==='confirmed'?btn('변경 요청',`customerChange('${b.id}','change')`)+btn('취소 요청',`customerChange('${b.id}','cancel')`):''}${['confirmed','pending','pending_payment'].includes(b.status)?btn('복구 코드 발급',`issueRecovery('${b.id}')`):''}</div>`).join('')+(r.bookings.length?'':'<p>이 브라우저 세션에 등록된 예약이 없습니다.</p>')+r.requests.map(x=>`<p class="muted">${x.action==='cancel'?'취소':'변경'} 요청: ${e(x.state==='pending'?'승인 대기':x.state==='approved'?'승인 완료':'거절')}</p>`).join('')+btn('다른 기기 예약 불러오기','recoverModal()')+'<p class="muted">외부 플랫폼의 환불은 해당 판매처에서 진행하세요.</p>')})}
function customerChange(id,action){modal(action==='cancel'?'예약 취소 확인':'예약 변경 확인',(action==='change'?label('변경할 업체 현지 시간',input('customer-start','','datetime-local')):'<p>예약 취소를 요청합니다. 결제 환불은 별도입니다.</p>')+btn('확인 및 요청',`act(async()=>{let r=await api('/api/customer/bookings/${id}/change',{token:chatSession,action:'${action}',start:$('#customer-start')?.value||'',confirmed:true});toast(r.state==='approved'?'요청 처리 완료':'업체 승인 대기');await customerBookings()})`,'primary'))}
async function customerRequest(){await act(async()=>{let t=await getChatSession(),rs=await api('/api/customer/requests/'+enc(t));if(!rs.length)throw Error('등록 가능한 업무가 없습니다.');modal('업무 요청',label('유형',select('req-kind',rs.map(k=>[k,({quote:'견적 요청',complaints:'불만·민원',tasks:'기타 요청'})[k]]),rs[0]))+label('제목',input('req-title'))+label('상세 내용',ta('req-detail'))+btn('확인 및 접수',"act(async()=>{let r=await api('/api/customer/requests',{token:chatSession,kind:val('req-kind'),title:val('req-title'),details:val('req-detail'),confirmed:true});$('.modal').remove();toast(r.duplicate?'이미 접수된 요청이 있습니다.':'요청이 접수되었습니다.')})",'primary'))})}
async function convertModal(){await act(async()=>{let t=await api('/api/inbox/'+threadId),ks=['crm','quote','tasks','leads','complaints'].filter(has);modal('상담에서 업무 등록',label('분류',select('convert-kind',ks.map(k=>[k,cfg.catalog.addons.find(x=>x.id===k).name]),ks[0]))+label('제목',input('convert-title',(t.messages.find(x=>x.role==='user')?.body||'상담 요청').slice(0,120)))+label('내용',ta('convert-detail',t.messages.map(x=>x.role+': '+x.body).join('\n').slice(0,2000)))+btn('등록',"act(async()=>{let r=await api('/api/inbox/'+threadId+'/work',{kind:val('convert-kind'),title:val('convert-title'),details:val('convert-detail')});$('.modal').remove();toast(r.duplicate?'이미 등록된 업무입니다.':'업무 등록 완료')})",'primary'))})}
async function workEdit(id){await act(async()=>{let w=(await api('/api/work')).find(x=>x.id===id);modal('업무 수정',label('제목',input('edit-title',w.title))+label('내용',ta('edit-details',w.details))+label('상태',select('edit-status',[['open','진행 중'],['pending','대기'],['resolved','완료']],w.status))+btn('저장',`act(async()=>{await api('/api/work/${id}',{title:val('edit-title'),details:val('edit-details'),status:val('edit-status')},'PATCH');$('.modal').remove();render()})`,'primary'))})}
async function workDelete(id){if(!confirm('업무를 삭제할까요?'))return;await act(async()=>{await api('/api/work/'+id,undefined,'DELETE');render()})}
const oldAlerts=alerts;alerts=async function(){let html=await oldAlerts(),ev=await api('/api/events');html+=card('업무 알림 기록',btn('모두 읽음',"act(async()=>{await api('/api/events/read',{});render()})")+ev.map(x=>`<div class="line"><b>${e(x.title)}</b><p class="muted">${e(new Date(x.created*1000).toLocaleString())} · ${x.seen?'읽음':'새 알림'}</p></div>`).join(''));if(has('email')){let n=await api('/api/notifications');html+=card('이메일 알림',label('수신 주소',input('notify-email',n.settings.email,'email'))+`<label><input type="checkbox" class="check" id="notify-enabled" ${n.settings.enabled?'checked':''}> 전송 활성화</label>`+btn('저장',"act(async()=>{await api('/api/notifications',{email:val('notify-email'),enabled:checked('notify-enabled')});render()})")+btn('대기 알림 보내기',"act(async()=>{let r=await api('/api/notifications/dispatch',{});toast('처리 '+r.results.length+'건');render()})",'primary')+`<p class="muted">${n.live_enabled?'실제 발송 활성화 · 검증 필요':cfg.demo?'로컬 모의 전송 · 이메일은 발송되지 않음':'실제 발송 비활성화'} / 관련 알림 옵션 필요 / ${n.auto_enabled?'자동 발송 설정 ON (워커 실행 필요)':'현재 수동 전송'}</p>`+n.deliveries.map(d=>`<div class="line">${e(d.status)} ${e(d.error)}</div>`).join(''))}return html};
let channelEvent=null;function channelModal(k){channelEvent=crypto.randomUUID();modal('외부 채널 메시지 검증',label('테스트 고객 ID',input('external-user','demo-user'))+label('질문',ta('external-text'))+btn('메시지 처리',`channelTest('${k}')`,'primary')+'<pre id="channel-result" class="scrolltext"></pre><p class="muted">외부 채널로 전송하지 않습니다. 실제 메시지 형식과 동일 상담 엔진을 테스트합니다.</p>')}
async function channelTest(k){await act(async()=>{let u=val('external-user'),m=val('external-text'),p=k==='naver'?{event:'send',user:u,textContent:{text:m}}:{userRequest:{user:{id:u},utterance:m}};let r=await api('/api/channels/simulate',{channel:k,event_id:channelEvent,payload:p});channelEvent=crypto.randomUUID();$('#channel-result').textContent=JSON.stringify(r,null,2)})}

let checkoutPending=null;
async function openCheckout(body){let q=await api('/api/billing/quote',body);checkoutPending=await api('/api/billing/orders',{...body,client:crypto.randomUUID()});modal('테스트 주문 확인',`<div class="price">${money(q.amount)}</div><p>주문 금액은 서버에서 산정합니다. 실제 결제되지 않습니다.</p><pre class="scrolltext">${e(JSON.stringify(q.items,null,2))}</pre>${btn('테스트 결제 완료','finishCheckout()','primary')}${btn('주문 취소','cancelCheckout()')}`)}
async function finishCheckout(){await act(async()=>{await api('/api/billing/orders/'+checkoutPending.id+'/sandbox-confirm',{});$('.modal').remove();await refresh();toast('테스트 주문 처리 완료');render()})}
async function cancelCheckout(){await act(async()=>{await api('/api/billing/orders/'+checkoutPending.id+'/cancel',{});$('.modal').remove();render()})}
async function orders(){let r=await api('/api/billing/history');return pageTop('주문 및 구독 내역','테스트 결제 내역입니다. 실제 청구되지 않습니다.')+billingTabs()+card('구독 상태',r.subscription?`<p>이용 종료: ${e(new Date(r.subscription.period_end*1000).toLocaleString())}</p><p>${r.subscription.cancel_at_end?'기간 종료 후 해지 예정':'테스트 구독 · 자동 갱신 없음'}</p>${!r.subscription.cancel_at_end&&r.subscription.period_end*1000>Date.now()?btn('기간 종료 후 해지',"act(async()=>{await api('/api/billing/subscription/cancel',{});render()})"):''}`:'<p>주문으로 생성된 구독이 없습니다.</p>')+card('주문 내역',r.orders.map(o=>`<div class="line"><b>${e(o.kind)} · ${money(o.amount)}</b><p>${e(o.status)} · ${e(new Date(o.created*1000).toLocaleString())}</p>${o.status==='pending'&&me.sandbox_allowed?btn('테스트 완료',`act(async()=>{await api('/api/billing/orders/${o.id}/sandbox-confirm',{});render()})`)+btn('취소',`act(async()=>{await api('/api/billing/orders/${o.id}/cancel',{});render()})`):''}</div>`).join('')||'<p>주문 내역 없음</p>')+card('메시지 충전 잔액',r.messages.map(m=>`<p>${e(m.kind)} ${m.n}건</p>`).join('')||'<p>충전 내역 없음</p>')+card('메시지 테스트 충전',me.sandbox_allowed?cfg.catalog.messages.map((m,i)=>`<div class="row between line"><span>${e(m.name)} ${m.quantity}건 · ${money(m.price)}</span>${btn('선택',`act(async()=>{let m=cfg.catalog.messages[${i}];await openCheckout({kind:'message',name:m.name,quantity:m.quantity})})`)}</div>`).join('')+'<p class="muted">메시지 충전 후 알림 화면에서 수신 설정을 진행하세요. 실제 발송은 외부 서비스 설정 및 검증이 필요합니다.</p>':'<p>실제 결제 미연결</p>')}

async function googleCalendarModal(){await act(async()=>{let r=await api('/api/integrations/calendar');modal('구글 캘린더 연결',`<p>${r.connected?'연결됨':r.configured?'연결 준비 완료':'환경변수 설정 필요'}</p><p class="muted">연결된 기본 캘린더의 외부 일정과 예약 충돌을 확인하고, CS AI 예약을 자동 동기화할 수 있습니다.</p>${r.configured?btn('Google 권한 연결',"location.href='/auth/calendar/connect'",'primary'):''}${r.connected?btn('외부 일정 조회','previewCalendar()')+`<div class="line"><label><input class="check" type="checkbox" id="gc-auto" ${r.policy.auto_sync?'checked':''}> 예약 자동 동기화</label><label><input class="check" type="checkbox" id="gc-busy" ${r.policy.block_busy?'checked':''}> 외부 일정 충돌 차단</label><p class="muted">${r.worker_enabled?'자동 워커 설정됨':'자동 워커 환경 설정 필요'} · 조회 범위 90일 · 5분 이상 지난 외부 일정은 예약 차단</p>${r.policy.error?`<p class="error">${e(r.policy.error)}</p>`:''}${r.errors.length?`<p class="error">동기화 재확인 필요 ${r.errors.length}건</p>`:''}</div>`+btn('자동 연동 설정 저장','saveCalendarPolicy()','primary')+btn('외부 일정 새로고침','refreshCalendarBusy()')+btn('연결 해제',"act(async()=>{await api('/api/integrations/calendar/disconnect',{});$('.modal').remove();render()})"):''}<div id="calendar-external"></div>`)})}
async function previewCalendar(){await act(async()=>{let r=await api('/api/integrations/calendar/preview');$('#calendar-external').innerHTML=r.map(x=>`<div class="line">${e(x.start.dateTime||x.start.date)} ~ ${e(x.end.dateTime||x.end.date)} ${x.owned?'· CS AI':''}</div>`).join('')||'<p>예정 일정 없음</p>'})}
async function syncCalendar(id){await act(async()=>{let r=await api('/api/integrations/calendar/sync/'+id,{});toast(r.status==='deleted'?'외부 예약 삭제 처리':'구글 캘린더 동기화 완료')})}
async function liveChannelModal(k){await act(async()=>{let r=await api('/api/integrations/channels/'+k);modal(k==='naver'?'네이버 톡톡 연결':'카카오 채널 연결',label(k==='naver'?'파트너 ID':'봇 ID',input('channel-partner',r.partner))+ (k==='naver'?label('보내기 API Authorization',input('channel-secret','','password')):'')+`<p class="muted">${r.configured?'HTTPS 연동 허용 환경':'실제 웹훅 비활성화 · 키 설정 및 HTTPS 필요'}</p><label><input type="checkbox" class="check" id="channel-active" ${r.active?'checked':''}> 실제 수신 활성화</label>`+btn('설정 저장',`saveLiveChannel('${k}')`,'primary')+(r.saved?label('Webhook / 스킬 URL (비공개)',input('channel-webhook',r.webhook))+btn('연결 해제',`act(async()=>{await api('/api/integrations/channels/${k}/disconnect',{});$('.modal').remove();render()})`):'')+`<p class="muted">실제 공급자 인증과 권한 검증 전 운영에 사용하지 마세요. 카카오는 승인된 콜백 설정이 필요합니다.</p>`+r.jobs.map(j=>`<div class="line">${e(j.status)} ${e(j.error)}</div>`).join(''))})}
async function saveLiveChannel(k){await act(async()=>{await api('/api/integrations/channels/'+k,{partner:val('channel-partner'),credential:$('#channel-secret')?.value||'',active:checked('channel-active')});await liveChannelModal(k)})}

const oldSettings=settings;settings=async function(){let html=oldSettings(),r=await api('/api/appearance');return html+card('채팅창 외형 및 링크',`${me.public_access?label('업체 로고',`<input type="file" id="logo-file" accept="image/png,image/jpeg,image/webp">`)+btn('로고 저장','saveLogo()')+btn('로고 제거',"act(async()=>{await api('/api/appearance',{logo:''});render()})"):'<p class="muted">유료 상담 구독 후 로고 설정 가능</p>'}${has('design')?label('채팅 테마',select('chat-theme',[['dark','기존 다크'],['toss','토스형'],['messenger','메신저형'],['premium','프리미엄형']],r.theme))+label('상담창 테마 색상',input('chat-color',r.color,'color'))+label('메시지 간격',select('chat-density',[['normal','기본'],['compact','촘촘하게'],['roomy','여유롭게']],r.density))+label('말풍선 모서리',select('chat-radius',[['rounded','둥글게'],['square','각지게']],r.bubble_radius))+btn('디자인 저장',"act(async()=>{await api('/api/appearance',{color:val('chat-color'),theme:val('chat-theme'),density:val('chat-density'),bubble_radius:val('chat-radius')});await refresh();render()})"):locked('design','상담창 테마 색상 설정')}${has('unbrand')?`<label><input type="checkbox" class="check" id="unbrand" ${r.unbrand?'checked':''}> CS AI 브랜드 간소화 (AI 안내는 유지)</label>`+btn('저장',"act(async()=>{await api('/api/appearance',{unbrand:checked('unbrand')});render()})"):locked('unbrand','브랜드 표시 간소화')}${has('custom_url')?label('지정 상담 주소 (영문 소문자/숫자)',input('alias',r.alias))+btn('주소 저장',"act(async()=>{await api('/api/appearance',{alias:val('alias')});render()})")+(r.alias?`<p><a href="/c/${e(r.alias)}" target="_blank" rel="noopener noreferrer">/c/${e(r.alias)}</a></p>`:''):locked('custom_url','원하는 상담 주소 설정')}`)};
async function saveLogo(){await act(async()=>{let f=$('#logo-file').files[0];if(!f||f.size>400000)throw Error('400KB 이하 이미지 파일을 선택하세요.');let data=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});await api('/api/appearance',{logo:data});render()})}
async function agents(){if(!has('extra_agent'))return pageTop('AI 상담원 관리','추가 AI 상담원을 운영할 수 있습니다.')+locked('extra_agent','별도 상담 링크, 상담 스타일, 개별 FAQ를 설정합니다.');let a=await api('/api/agents'),s=a?.settings||{brand:'추가 상담원',tone:'자연스럽고 정중하게',prompt:'등록된 정책으로만 상담하세요.',welcome:'안녕하세요. 무엇을 도와드릴까요?',fallback:'담당자 확인이 필요합니다.',emoji:false};return pageTop('AI 상담원 관리','기본 상담원 외 추가 1명 · 업체 공통 사용량과 예약 일정 공유')+card('추가 상담원 설정',label('상담원 이름',input('agent-brand',s.brand))+label('말투',input('agent-tone',s.tone))+label('첫 인사',input('agent-welcome',s.welcome))+label('모르는 질문 안내',ta('agent-fallback',s.fallback))+`<label><input class="check" id="agent-emoji" type="checkbox" ${s.emoji?'checked':''}> 이모지 사용</label>`+`<label><input type="checkbox" class="check" id="agent-enabled" ${a?.enabled?'checked':''}> 추가 상담원 공개</label>`+btn('저장','saveAgent()','primary')+(a?`<p>별도 상담 주소: <a href="/c/${e(a.slug)}" target="_blank" rel="noopener noreferrer">/c/${e(a.slug)}</a></p>`:'')+'<p class="muted">교육 지식은 상담원별로 분리되며, 예약 일정과 사용량은 업체 공통입니다.</p>')+(a?card('추가 상담원 교육',btn('교육 시작',`educationAgent='${a.id}';go('education')`,'primary')+`<pre class="scrolltext">${e(JSON.stringify(a.published,null,2))}</pre>`+(await api('/api/agents/versions')).map(v=>btn(new Date(v.created*1000).toLocaleString()+' 복원',`act(async()=>{await api('/api/agents/versions/${v.id}/restore',{});render()})`)).join('')):'')}
async function saveAgent(){await act(async()=>{await api('/api/agents',{brand:val('agent-brand'),tone:val('agent-tone'),welcome:val('agent-welcome'),fallback:val('agent-fallback'),emoji:checked('agent-emoji'),enabled:checked('agent-enabled')});render()})}

function showWorkDraft(w){$('#work-draft')?.remove();$('#messages').insertAdjacentHTML('beforeend',`<section id="work-draft" class="card booking-form"><h3>업무 요청 내용 확인</h3>${label('제목',input('draft-title',w.title))}${label('상세 내용',ta('draft-detail',w.details))}${btn('확인 및 접수',`submitWorkDraft('${w.kind}')`,'primary')}${btn('닫기',"$('#work-draft').remove()")}</section>`)}
