async function invites(){let rows=await api('/api/operator/invites');return pageTop('초청 및 체험 관리','발급 직후에만 원문 코드를 확인할 수 있습니다.')+card('초청 링크 발급',label('상담 체험',select('invite-chat',[['50','50회'],['100','100회'],['300','300회']],'50'))+label('교육 크레딧',input('invite-credit','100','number'))+label('체험 기간 (1~30일)',input('invite-days','14','number'))+btn('1회용 링크 발급','createInvite()','primary'))+card('발급 내역',rows.map(x=>`<div class="line"><b>${e(x.chat_limit)}회 · ${e(x.credit_limit)}C · ${e(x.days)}일</b><p class="muted">${x.revoked?'회수됨':x.used_by?'사용 완료':'수락 대기'} · 수락 기한 ${new Date(x.expires*1000).toLocaleString()}</p>${!x.revoked?btn('회수',`act(async()=>{await api('/api/operator/invites/${x.id}/revoke',{});render()})`):''}</div>`).join('')||'<p class="muted">아직 발급한 초청 링크가 없습니다.</p>')}
async function createInvite(){await act(async()=>{let x=await api('/api/operator/invites',{chat_limit:Number(val('invite-chat')),credit_limit:Number(val('invite-credit')),days:Number(val('invite-days'))});modal('초청 링크를 지금 복사하세요',`<p>이 코드는 다시 표시되지 않습니다. 초청 링크를 공유하세요. Google 로그인 뒤 체험을 수락할 수 있습니다.</p>${input('invite-code',location.origin+x.accept_path)}${btn('초청 링크 복사',"act(async()=>{await navigator.clipboard.writeText(val('invite-code'));toast('복사 완료')})")}`);render()})}
async function costs(){let x=await api('/api/operator/costs');return pageTop('사용량 및 원가','운영자 전용 · 모의 사용량은 실제 매출이나 원가에 포함하지 않습니다.')+card('모델 설정',`<p>교육: ${e(x.models.training)} · 상담: ${e(x.models.chat)}</p><p class="muted">공식 단가 기준의 추정치이며, 실제 청구서·세금·서버비와 다를 수 있습니다.</p>`)+card('모델 사용량',table(['유형','모델','모드','입력','출력','추정 USD'],x.rows.map(r=>[r.kind,r.model,r.mode,Number(r.input_tokens).toLocaleString(),Number(r.output_tokens).toLocaleString(),Number(r.estimated_cost_usd).toFixed(6)])))}
async function submitWorkDraft(k){await act(async()=>{let r=await api('/api/customer/requests',{token:chatSession,kind:k,title:val('draft-title'),details:val('draft-detail'),confirmed:true});$('#work-draft').innerHTML=`<p>${r.duplicate?'이미 접수된 요청입니다.':'요청이 접수되었습니다. 담당자 확인 후 안내드립니다.'}</p>`})}

window.addEventListener('hashchange',()=>{if(!publicMode){if(location.hash!=='#test'){chatSession=null;chatMessages=[]}if(location.hash!=='#fields')fields=null;render()}});init();

async function issueRecovery(id){if(!confirm('기존 복구 코드가 있다면 폐기됩니다. 새 코드를 발급할까요?'))return;await act(async()=>{let r=await api('/api/customer/bookings/'+id+'/recovery-code',{token:await getChatSession()});modal('예약 복구 코드',`<p>다른 기기에서 이 예약만 불러올 수 있는 일회용 코드입니다. 누구에게도 공유하지 마세요. 기존 상담 내용은 이전되지 않습니다.</p>${input('recovery-issued',r.code)}<p class="muted">만료: ${e(new Date(r.expires*1000).toLocaleString())}</p>${btn('코드 복사',"act(async()=>{await navigator.clipboard.writeText(val('recovery-issued'));toast('복사 완료')})")}`)})}
function recoverModal(){modal('예약 불러오기',label('예약 복구 코드',input('recovery-code'))+'<p class="muted">동일 업체의 상담 링크에서 발급받은 코드를 입력하세요. 이 기기로 예약 관리 권한이 이전됩니다.</p>'+btn('예약 불러오기',"act(async()=>{await api('/api/customer/bookings/recover',{token:await getChatSession(),code:val('recovery-code').trim()});toast('예약 불러오기 완료');customerBookings()})",'primary'))}

function showEducationQuote(q){modal('AI 교육 비용 확인',`<p>최대 ${q.maxCredits} C 예약 · 보유 ${q.credits} C</p><p>교육 후 실제 사용량만 차감되며, 승인해야 반영됩니다.</p>${q.enough?btn('교육 시작',`act(async()=>{let r=await api('/api/training/${q.id}/run',{});$('.modal')?.remove();await refresh();toast('교육 결과 생성 · '+r.cost+' C');if(route==='education')render();else go('education')})`,'primary'):btn('크레딧 충전',"$('.modal')?.remove();go('credits')")}`)}

async function developer(){if(!has('external_api'))return pageTop('개발자 센터','구매한 기능을 외부 서비스에서 호출합니다.')+locked('external_api','API 키와 상담·예약·업무·교육 API를 제공합니다.');let x=await api('/api/developer/keys');return pageTop('개발자 센터','서버 전용 API 키 · 기존 상담량 및 교육 크레딧 사용')+card('API 키 발급',label('키 이름',input('dev-key-name','외부 서비스'))+x.scopes.map(s=>`<label class="row line"><input type="checkbox" class="check dev-scope" value="${e(s)}"> ${e(s)}</label>`).join('')+btn('API 키 발급','createDevKey()','primary'))+card('API 키 관리',x.keys.map(k=>`<div class="line"><b>${e(k.label)}</b><p>${e(k.scopes.join(', '))} · ${k.revoked?'폐기됨':'활성'}</p>${!k.revoked?btn('폐기',`act(async()=>{await api('/api/developer/keys/${k.id}/revoke',{});render()})`):''}</div>`).join('')||'<p>발급한 키가 없습니다.</p>')+card('개발 문서','<p>Authorization: Bearer YOUR_KEY</p><p>POST /v1/chat/sessions → POST /v1/chat</p><p>구매 기능에 따라 예약, 업무, 교육, 통계 API를 사용할 수 있습니다.</p><a href="/api/docs" target="_blank" rel="noopener noreferrer">API 문서 열기</a><p class="muted">키는 서버 환경변수에 보관하고 브라우저 코드에 노출하지 마세요.</p>')}
async function createDevKey(){await act(async()=>{let r=await api('/api/developer/keys',{label:val('dev-key-name'),scopes:[...document.querySelectorAll('.dev-scope:checked')].map(x=>x.value)});modal('API 키 발급 완료',`<p>지금 한 번만 확인할 수 있습니다. 안전하게 보관하세요.</p>${input('issued-dev-key',r.key)}${btn('복사',"act(async()=>{await navigator.clipboard.writeText(val('issued-dev-key'));toast('복사 완료')})")}`);render()})}

async function importEducationUrl(){await act(async()=>{let r=await api('/api/files/url',{url:val('education-url')});toast(r.duplicate?'이미 등록된 자료입니다.':'웹페이지 자료 등록 완료');render()})}

async function saveCalendarPolicy(){await act(async()=>{await api('/api/integrations/calendar/policy',{auto_sync:checked('gc-auto'),block_busy:checked('gc-busy')});toast('캘린더 설정 저장 완료');googleCalendarModal()})}
async function refreshCalendarBusy(){await act(async()=>{let r=await api('/api/integrations/calendar/refresh',{});toast('외부 일정 '+r.count+'건 확인');googleCalendarModal()})}

async function crmPanel(){let contacts=await api('/api/crm/contacts');return card('고객 CRM',btn('고객 등록','crmEdit()','primary')+contacts.map(x=>`<div class="line"><b>${e(x.name)}</b><p>${e([x.email,x.phone].filter(Boolean).join(' · '))}</p><p>${e(x.notes)}</p>${x.threads.map(t=>btn('상담 이력',`threadId='${t.thread}';go('inbox')`)).join('')}${btn('수정',`crmEdit('${x.id}')`)}${btn('삭제',`crmDelete('${x.id}')`)}</div>`).join(''))}
async function crmEdit(id=''){await act(async()=>{let items=await api('/api/crm/contacts'),x=items.find(z=>z.id===id)||{},threads=(await api('/api/inbox')).filter(t=>t.kind!=='test');modal(id?'고객 정보 수정':'고객 등록',label('이름',input('crm-name',x.name||''))+label('이메일',input('crm-email',x.email||'','email'))+label('연락처',input('crm-phone',x.phone||''))+label('메모',ta('crm-notes',x.notes||''))+label('연결할 상담',select('crm-thread',[['','선택 안 함'],...threads.map(t=>[t.id,(t.last||'고객 상담').slice(0,50)])],''))+btn('저장',`saveCrm('${id}')`,'primary'))})}
async function saveCrm(id){await act(async()=>{await api('/api/crm/contacts'+(id?'/'+id:''),{name:val('crm-name'),email:val('crm-email'),phone:val('crm-phone'),notes:val('crm-notes'),thread:val('crm-thread')},id?'PATCH':'POST');$('.modal').remove();render()})}
async function crmDelete(id){if(!confirm('고객 정보만 삭제하고 상담 내역은 유지할까요?'))return;await act(async()=>{await api('/api/crm/contacts/'+id,undefined,'DELETE');render()})}
async function leadPanel(){let xs=await api('/api/leads'),labels={inquiry:'일반 문의',interested:'관심 고객',ready:'구매·예약 의사'};return card('잠재 고객 자동 분류',`<p class="muted">실제 상담의 구매 의사에 따라 분류하며, 담당자가 수정할 수 있습니다.</p>`+xs.map(x=>`<div class="line"><b>${e(labels[x.stage]||x.stage)}</b><p class="muted">${e(x.source==='ai'?'AI 분류':x.source==='staff'?'담당자 분류':'규칙 기반 분류')}</p>${select('lead-'+x.thread,Object.entries(labels),x.stage)}${btn('분류 저장',`saveLead('${x.thread}')`)}${btn('상담 열기',`threadId='${x.thread}';go('inbox')`)}</div>`).join(''))}
async function saveLead(id){await act(async()=>{await api('/api/leads/'+id,{stage:val('lead-'+id)},'PATCH');render()})}
async function quotePanel(list){let items=await api('/api/quotes/items'),offers=await api('/api/quotes/offers');return card('견적 상품·가격 관리',label('상품명',input('quote-item-name'))+label('원화 단가',input('quote-item-price','','number'))+btn('상품 등록','saveQuoteItem()','primary')+items.map(x=>`<div class="line"><b>${e(x.name)} · ${money(x.price)}</b> ${e(x.active?'판매 중':'중지')} ${btn('수정',`quoteItemEdit('${x.id}')`)}</div>`).join(''))+card('견적서 작성 및 전송',`<p class="muted">등록된 단가로 계산합니다. 담당자 승인 전에는 고객에게 금액을 전송하지 않습니다.</p>`+list.filter(x=>x.kind==='quote').map(x=>`<div class="line"><b>${e(x.title)}</b><p>${e(x.details)}</p>${btn('견적서 작성',`quoteCompose('${x.id}')`)}</div>`).join('')+offers.map(x=>`<div class="line"><b>${money(x.amount)}</b><p>${e(x.items.map(z=>z.name+' × '+z.quantity).join(', '))}</p><small>${x.status==='sent'?'전송 완료':'검토 대기'}</small>${x.status==='draft'?btn('고객에게 전송',`sendQuote('${x.id}')`,'primary'):''}</div>`).join(''))}
async function saveQuoteItem(){await act(async()=>{await api('/api/quotes/items',{name:val('quote-item-name'),price:Number(val('quote-item-price'))});render()})}
async function quoteItemEdit(id){await act(async()=>{let x=(await api('/api/quotes/items')).find(z=>z.id===id);modal('견적 상품 수정',label('상품명',input('qe-name',x.name))+label('단가',input('qe-price',x.price,'number'))+`<label><input class="check" type="checkbox" id="qe-active" ${x.active?'checked':''}> 판매 중</label>`+btn('저장',`act(async()=>{await api('/api/quotes/items',{id:'${id}',name:val('qe-name'),price:Number(val('qe-price')),active:checked('qe-active')});$('.modal').remove();render()})`,'primary'))})}
async function quoteCompose(id){await act(async()=>{let items=(await api('/api/quotes/items')).filter(x=>x.active);if(!items.length)throw Error('견적 상품을 먼저 등록하세요.');modal('견적 작성',items.map(x=>`<div class="line"><label>${e(x.name)} · ${money(x.price)}</label><input class="quote-qty" data-id="${e(x.id)}" type="number" min="0" max="1000" value="0"></div>`).join('')+label('추가 안내',ta('quote-note'))+btn('서버 금액 계산 및 저장',`createQuote('${id}')`,'primary'))})}
async function createQuote(id){await act(async()=>{let items=[...document.querySelectorAll('.quote-qty')].map(x=>({id:x.dataset.id,quantity:Number(x.value)})).filter(x=>x.quantity>0);let r=await api('/api/quotes/offers',{work:id,items,note:val('quote-note')});$('.modal').remove();toast('견적 '+money(r.amount)+' 저장 완료');render()})}
async function sendQuote(id){if(!confirm('검토한 견적 금액을 고객 채팅창에 전송할까요?'))return;await act(async()=>{await api('/api/quotes/offers/'+id+'/send',{confirmed:true});toast('견적 전송 완료');render()})}

function landingBenefits(){
 const benefits=[
 ['내 사업을 가장 잘 이해하는, 또 하나의 나','단순한 자동 답변기가 아니라 내 사업을 직접 교육하는 클론 상담사입니다.',['나의 사업 지식, 영업 노하우, 내부 상담 기준을 교육할 수 있습니다.','나처럼 상담하는 나의 분신. 말투와 응대 스타일도 직접 수정할 수 있습니다.','업무에 필요한 사업 비밀과 민감한 내부 정보는 공개 범위를 검토하고 필요한 만큼만 제공하세요.','파트너처럼 사업을 이해하도록 교육하되, 고객에게 공개할 정보는 직접 관리할 수 있습니다.']],
 ['사람을 고용할 때의 부담을 줄이세요','사람과 함께하는 일의 가치는 그대로. 반복 상담 업무에는 다른 선택지가 있습니다.',['채용과 면접, 인수인계, 직원 간 인간관계에서 생기는 스트레스를 줄일 수 있습니다.','AI는 불평이나 불만을 표현하는 직원도, 일을 배워 경쟁 사업으로 독립하거나 퇴사하는 직원도 아닙니다.','AI 구독 자체에는 근로계약, 해고·퇴직 절차, 퇴직금, 식대가 발생하지 않습니다.','해당 업무에 추가 고용이 필요하지 않다면 고용 관련 분쟁과 신고 대응 부담도 줄일 수 있습니다.']],
 ['24시간, 상담부터 비서 역할까지','내가 잠들거나 다른 업무를 할 때도 반복되는 문의를 처리할 수 있습니다.',['시간과 장소에 구애받지 않는 24시간 고객 응대.','상담부터 예약, 일정 관리, 견적, 고객 관리 등 필요한 업무까지 연결합니다.','상담원에서 비서 역할까지, 필요한 서비스와 채널을 추가할 수 있습니다.','정확한 교육과 담당자 확인을 통해 일의 품질을 관리할 수 있습니다.']],
 ['가르칠수록 나아지고, 필요한 만큼만 비용을','직접 직원을 고용하는 편이 더 경제적인 상황도 있습니다. 하지만 비용만이 전부는 아닙니다.',['잘못된 답변과 새로운 질문을 교육하고 검토하면 업무 수행 품질을 개선할 수 있습니다.','사용량과 필요한 기능에 맞는 저렴한 구독으로 인건비와 반복 업무 비용 절감을 기대할 수 있습니다.','교육이 쌓일수록 내 사업에 더 맞는 상담원이 됩니다.','새로운 기능을 필요한 만큼 확장하고, 반복 상담에 쓰던 시간을 본업에 돌리세요.']]
 ];
 return `<section class="landing-benefits" aria-labelledby="landing-benefit-title"><div class="landing-benefits-inner"><p class="landing-benefits-kicker">WHY CS AI</p><h2 id="landing-benefit-title">나의 사업을 이해하는<br>나의 클론 상담사.</h2><p class="landing-lead">직원을 고용하는 편이 더 저렴할 수도 있습니다. 하지만 나의 방식으로 일하고, 내가 직접 교육하며, 반복되는 상담과 고용 부담을 줄이는 것은 또 다른 가치입니다.</p><div class="landing-benefit-grid">${benefits.map(([h,p,items],i)=>`<article class="landing-benefit"><span class="landing-benefit-number">${String(i+1).padStart(2,'0')}</span><h3>${e(h)}</h3><p>${e(p)}</p><ul>${items.map(x=>`<li>${e(x)}</li>`).join('')}</ul></article>`).join('')}</div><div class="landing-benefits-cta"><div><h3>오늘부터, 나의 클론 상담사를 교육하세요.</h3><p>첫 상담 테스트 1회와 교육 크레딧 20C로 시작할 수 있습니다.</p></div><button class="primary" type="button" onclick="google()">Google로 시작하기</button></div><p class="landing-benefits-note">AI 응답에는 오류가 있을 수 있으며, 24시간 이용은 서비스 상태와 구독 한도에 따릅니다. 예약·견적·외부 연동 등은 해당 기능의 구매 및 설정이 필요하며 일부는 개발·검증 중입니다. 교육 자료는 서비스 및 AI 처리에 사용될 수 있으므로 비밀번호, 결제 정보, 불필요한 개인정보는 입력하지 마세요. 정보 유출이 없다고 보장할 수 없으며, 실제 데이터 보호와 비용 절감은 운영 방식에 따라 달라집니다.</p></div></section>`
}

let analyticsDays=30;
async function analyticsPanel(){let r=await api('/api/analytics?days='+analyticsDays),max=Math.max(1,...r.daily.map(d=>d.threads));return card('고급 상담 통계',label('조회 기간',select('analytics-days',[['7','최근 7일'],['30','최근 30일'],['90','최근 90일']],String(analyticsDays)))+btn('조회', "analyticsDays=Number(val('analytics-days'));render()")+table(['고객 상담','메시지','미학습','완료'],[[r.threads,r.messages,r.unknown,r.resolved]])+`<div style="display:flex;align-items:end;height:120px;gap:2px;margin:18px 0">${r.daily.map(d=>`<div title="${e(d.date)}: ${d.threads}건" style="flex:1;min-width:0;background:#3182f6;border-radius:3px 3px 0 0;height:${Math.max(1,d.threads/max*100)}%"></div>`).join('')}</div><p class="muted">일별 고객 상담 수 · 관리자 테스트 제외</p>`+table(['채널','상태','건수'],r.channels.map(x=>[x.kind,states[x.status]||x.status,x.n]))+table(['예약 상태','건수'],r.bookings.map(x=>[states[x.status]||x.status,x.n]))+table(['업무 유형','상태','건수'],r.work.map(x=>[cfg.catalog.addons.find(a=>a.id===x.kind)?.name||x.kind,states[x.status]||x.status,x.n])))}
const reportAlerts=alerts;
alerts=async function(){let html=await reportAlerts();if(!has('report'))return html;let r=await api('/api/reports');return html+card('일간·주간 상담 리포트',label('생성 주기',select('report-frequency',[['daily','매일'],['weekly','매주']],r.settings.frequency))+`<label><input class="check" type="checkbox" id="report-enabled" ${r.settings.enabled?'checked':''}> 자동 생성</label><p class="muted">${r.worker_enabled?'자동 워커 설정됨':'자동 워커 환경 설정 필요'} · 지난 완료 기간 기준 집계</p>`+btn('설정 저장','saveReportSettings()','primary')+btn('리포트 생성','generateReport()')+r.reports.map(x=>`<div class="line"><b>${e(x.period)}</b><p>고객 상담 ${x.summary.threads}건 · 완료 ${x.summary.resolved}건 · 미학습 ${x.summary.unknown}건 · 메시지 ${x.summary.messages}개</p></div>`).join(''))}
async function saveReportSettings(){await act(async()=>{await api('/api/reports/settings',{frequency:val('report-frequency'),enabled:checked('report-enabled')});toast('설정 저장 완료');render()})}
async function generateReport(){await act(async()=>{await api('/api/reports/generate',{});toast('리포트 생성 완료');render()})}

const pushAlerts=alerts;
alerts=async function(){let html=await pushAlerts();if(!has('push'))return html+locked('push','브라우저가 닫혀 있어도 지원되는 기기에서 업무 알림을 받을 수 있습니다.');let r=await api('/api/push');return html+card('웹 푸시 알림',`<p class="muted">${r.configured?(r.live?'실제 발송 활성화':'모의 발송 모드'):'VAPID 환경변수 설정 필요'} · 구매한 알림 종류만 발송 · 지원 브라우저 및 HTTPS 필요</p>`+btn('이 기기 알림 등록','registerPush()','primary')+btn('이 기기 알림 해제','unregisterPush()')+r.devices.map(d=>`<div class="line"><b>등록 기기</b><p>${e(new Date(d.created*1000).toLocaleString())}</p>${btn('등록 해제',`removePush('${d.id}')`)}</div>`).join('')+r.deliveries.map(d=>`<p class="muted">${e(new Date(d.created*1000).toLocaleString())} · ${e(d.status)}</p>`).join(''))};
function vapidBytes(key){let b=atob(key.replace(/-/g,'+').replace(/_/g,'/')+'='.repeat((4-key.length%4)%4));return Uint8Array.from(b,x=>x.charCodeAt(0))}
async function registerPush(){await act(async()=>{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('웹 푸시를 지원하는 HTTPS 브라우저가 필요합니다.');let r=await api('/api/push');if(!r.configured)throw Error('푸시 서버 설정이 필요합니다.');if(await Notification.requestPermission()!=='granted')throw Error('브라우저에서 알림 권한을 허용하세요.');let reg=await navigator.serviceWorker.register('/push-sw.js');await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub)sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(r.public_key)});let x=await api('/api/push',sub.toJSON());localStorage.setItem('csai-push-id',x.id);toast('이 기기 등록 완료');render()})}
async function unregisterPush(){await act(async()=>{let id=localStorage.getItem('csai-push-id');if(id)await api('/api/push/'+id,undefined,'DELETE');let reg=await navigator.serviceWorker?.getRegistration('/');let sub=await reg?.pushManager.getSubscription();if(sub)await sub.unsubscribe();localStorage.removeItem('csai-push-id');toast('알림 해제 완료');render()})}
async function removePush(id){if(!confirm('이 기기의 푸시 등록을 해제할까요?'))return;await act(async()=>{if(localStorage.getItem('csai-push-id')===id){await unregisterPush();return}await api('/api/push/'+id,undefined,'DELETE');render()})}

const domainChannels=channels;
channels=async function(){let html=await domainChannels();if(!has('domain'))return html+locked('domain','보유한 도메인에서 고객 상담을 제공합니다.');let r=await api('/api/domains'),d=r.domain;return html+card('자체 도메인',label('고객 상담 도메인',input('domain-host',d?.hostname||'','text','chat.example.com'))+btn('등록','saveDomain()','primary')+`<p class="muted">${r.configured?'Cloudflare 확인 설정 완료':'운영자 Cloudflare for SaaS 설정 필요'}</p>`+(d?`<p>상태: ${d.active?'DNS·HTTPS 검증 완료':'확인 대기'}</p><p class="muted">아래 DNS 레코드를 추가하고 운영자가 Custom Hostname 및 TLS 인증서를 연결한 후 확인하세요.</p>`+table(['종류','이름','값'],[['TXT',d.txt_name,d.txt_value],['CNAME',d.hostname,r.target||'운영자 설정 필요']])+btn('DNS 및 HTTPS 확인','verifyDomain()')+btn('연결 해제','removeDomain()')+(d.active?`<p><a href="https://${e(d.hostname)}" target="_blank" rel="noopener noreferrer">고객 상담 열기</a></p>`:''):''))};
async function saveDomain(){await act(async()=>{await api('/api/domains',{hostname:val('domain-host')});render()})}
async function verifyDomain(){await act(async()=>{await api('/api/domains/verify',{});toast('DNS·HTTPS 확인 완료');render()})}
async function removeDomain(){if(!confirm('자체 도메인 연결을 해제할까요?'))return;await act(async()=>{await api('/api/domains',undefined,'DELETE');render()})}

const smsAlerts=alerts;
alerts=async function(){let html=await smsAlerts(),r=await api('/api/message-notifications'),s=r.settings||{};return html+card('알림톡·SMS 업무 알림',`<p class="muted">등록한 본인 휴대전화로 구매한 업무 알림을 받습니다. 1건당 충전 잔액 1건을 차감하며, 실제 발송에는 번호 소유권 확인이 필요합니다.</p><p>SMS ${r.balance.SMS}건 · 알림톡 ${r.balance['알림톡']}건</p>`+label('수신 번호',input('sms-phone','','tel',s.phone||'01012345678'))+label('수신 방식',select('sms-kind',[['SMS','SMS'],['알림톡','알림톡']],s.kind||'SMS'))+`<p><label><input class="check" type="checkbox" id="sms-enabled" ${s.enabled?'checked':''}> 자동 발송</label></p><p><label><input class="check" type="checkbox" id="sms-consent"> 본인 번호이며 업무 알림 수신 및 연락처 처리에 동의합니다.</label></p><p class="muted">${s.verified?'번호 확인 완료':'번호 확인 대기'} · ${r.live[s.kind||'SMS']?'실제 발송 활성화':cfg.demo?'모의 발송':'실제 발송 미설정'}</p>`+btn('저장','saveMessageNotify()','primary')+btn('알림 해제','disableMessageNotify()')+btn('메시지 충전',"go('orders')")+table(['유형','발송 상태','일시'],r.deliveries.map(x=>[x.kind,x.status,new Date(x.created*1000).toLocaleString()])))};
async function saveMessageNotify(){await act(async()=>{await api('/api/message-notifications',{phone:val('sms-phone'),kind:val('sms-kind'),enabled:checked('sms-enabled'),consent:checked('sms-consent')});toast('설정 저장 완료');render()})}
async function disableMessageNotify(){await act(async()=>{await api('/api/message-notifications',undefined,'DELETE');render()})}
const messageInvites=invites;
invites=async function(){let html=await messageInvites(),xs=await api('/api/operator/message-notifications');return html+card('업무 알림 번호 확인',`<p class="muted">실제 번호 소유권과 수신 동의를 별도로 확인한 뒤 승인하세요. 승인 자체는 메시지를 보내지 않습니다.</p>`+xs.map(x=>`<div class="line"><b>${e(x.phone)}</b><p>${e(x.kind)} · ${x.verified?'확인 완료':'확인 필요'}</p>${x.verified?'':btn('소유권 확인 승인',`verifyMessagePhone('${x.ws}','${x.phone}')`)}</div>`).join(''))};
async function verifyMessagePhone(ws,phone){if(!confirm('번호 소유권 및 수신 동의를 실제로 확인했습니까?'))return;await act(async()=>{await api('/api/operator/message-notifications/'+ws+'/verify',{phone,confirmed:true});render()})}
